 "content": "from collections import Counter


def transform(grid):
    """Zero the dominant color; recolor the minority color as that dominant color."""
    counts = Counter(value for row in grid for value in row)
    if len(counts) != 2:
        raise ValueError(f"Expected exactly two colors, got {sorted(counts)}")
    dominant = max(counts, key=counts.get)
    minority = next(color for color in counts if color != dominant)
    mapping = {dominant: 0, minority: dominant}
    return [[mapping[value] for value in row] for row in grid]
